import matplotlib

matplotlib.use("Agg")

import matplotlib.pyplot as plt
import pandas as pd

RC_PARAMS = {
    "font.size": 8,
    "axes.labelsize": 8,
    "axes.titlesize": 8,
    "xtick.labelsize": 7,
    "ytick.labelsize": 7,
    "legend.fontsize": 7,
    "axes.linewidth": 0.7,
    "xtick.major.width": 0.7,
    "ytick.major.width": 0.7,
}

FIGSIZE = (7, 4.2)
PALETTE = ["#0072B2", "#D55E00", "#009E73", "#CC79A7", "#E69F00", "#56B4E9", "#8C564B", "#000000"]
RECEDED_ALPHA = 0.4

DATA_PATH = "data/training.csv"
X_FIELD = "epoch"
Y_FIELD = "accuracy"
GROUP = "model"
SERIES_ORDER = ["baseline", "+augment", "+distill", "ours"]
EMPHASIS = None
STEM = "08-compact-double-column"
FORMATS = ["png", "svg", "pdf"]
DPI = 600


def load():
    return pd.read_csv(DATA_PATH)


def series_names(frame):
    if SERIES_ORDER is not None:
        return list(SERIES_ORDER)
    return sorted(frame[GROUP].dropna().unique().tolist(), key=str)


def series_style(name, index):
    colour = PALETTE[index % len(PALETTE)]
    if EMPHASIS is None:
        return {"colour": colour, "width": 1.2, "alpha": 1.0, "zorder": 2}
    if name == EMPHASIS:
        return {"colour": colour, "width": 1.9, "alpha": 1.0, "zorder": 3}
    return {"colour": colour, "width": 0.9, "alpha": RECEDED_ALPHA, "zorder": 1}


def aggregate(df):
    keys = [X_FIELD, GROUP]
    return df.groupby(keys, as_index=False)[Y_FIELD].mean()


def draw(ax, df):
    df = aggregate(df)
    names = series_names(df)
    for index, name in enumerate(names):
        frame = df[df[GROUP] == name]
        frame = frame.sort_values(X_FIELD)
        style = series_style(name, index)
        ax.plot(
            frame[X_FIELD],
            frame[Y_FIELD],
            label=str(name),
            color=style["colour"],
            linewidth=style["width"],
            alpha=style["alpha"],
            zorder=style["zorder"],
        )


def finish(fig, ax):
    ax.set_xlabel("Training epoch")
    ax.set_ylabel("Test accuracy (%)")
    ax.set_ylim(0, 90)
    ax.set_title("Accuracy over training, double column")
    ax.grid(True, linewidth=0.4, alpha=0.5)
    for side in ("top", "right"):
        ax.spines[side].set_visible(False)
    ax.legend(
        title=None,
        frameon=False,
        loc="best",
    )
    fig.tight_layout()


def main():
    df = load()
    with plt.rc_context(RC_PARAMS):
        fig, ax = plt.subplots(figsize=FIGSIZE)
        draw(ax, df)
        finish(fig, ax)
        for fmt in FORMATS:
            path = f"{STEM}.{fmt}"
            kwargs = {"bbox_inches": "tight"}
            if fmt == "png":
                kwargs["dpi"] = DPI
            fig.savefig(path, **kwargs)
            print(f"wrote {path}")
    plt.close(fig)


if __name__ == "__main__":
    main()
